import {questions,subjects,shuffledOptions} from './questions.js';
import {drawWorld} from './world.js';
import {loadAllArt} from './art.js';
const $=id=>document.getElementById(id),state={cls:0,element:1,pet:1,zone:0,wins:[0,0,0]};
let hp=100,score=0,round=1,event=null,phase='ready',deck=[],q,options,timer=null,remaining=0,last=0;
const dialog=$('quiz');
function nextDeck(){deck=questions.filter(x=>$('subject').value==='all'||x.subject===$('subject').value).slice();for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}}
function lock(value){for(const id of ['subject','hero','pace'])$(id).disabled=value;$('attack').disabled=value;}
function ask(){if(phase!=='ready')return;if(!deck.length)nextDeck();q=deck.pop();options=shuffledOptions(q);phase='question';lock(true);$('question').textContent=q.prompt;$('qsubject').textContent='Lớp 2 · '+subjects[q.subject];$('feedback').textContent='';$('continue').hidden=true;$('answers').replaceChildren();options.forEach((o,i)=>{const b=document.createElement('button');b.textContent='ABCD'[i]+'. '+o.text;b.onclick=()=>answer(i);$('answers').append(b);});remaining=Number($('pace').value)*1000;last=performance.now();$('timer').textContent=remaining?'15 giây':'Cứ bình tĩnh suy nghĩ nhé';dialog.showModal();$('answers').firstElementChild.focus();if(remaining)timer=setInterval(()=>{const now=performance.now();if(!document.hidden)remaining-=now-last;last=now;$('timer').textContent=Math.max(0,Math.ceil(remaining/1000))+' giây';if(remaining<=0)answer(-1);},100);}
function answer(index){if(phase!=='question')return;phase='feedback';clearInterval(timer);const correct=options[index]?.correct===true;[...$('answers').children].forEach((b,i)=>{b.disabled=true;if(options[i].correct)b.classList.add('correct');else if(i===index)b.classList.add('wrong');});$('feedback').textContent=(correct?'Đúng rồi! Phép màu đã sẵn sàng. ':index<0?'Hết giờ rồi. Mình cùng xem lời giải nhé. ':'Chưa đúng rồi. Mình cùng học nhé. ')+q.explanation;$('continue').textContent=correct?'✦ Tung phép!':'Mình đã hiểu · tiếp tục';$('continue').hidden=false;$('continue').focus();$('continue').onclick=()=>resolve(correct);}
function resolve(correct){if(phase!=='feedback')return;phase='animation';dialog.close();if(correct){score++;hp=Math.max(0,hp-25);event={time:performance.now(),damage:25,skill:true};$('message').textContent='Chính xác! Sương mù đang tan dần…';}else $('message').textContent='Linh thú tạo khiên giúp em. Hãy thử câu tiếp theo!';$('hp').value=hp;$('score').textContent=score+' câu đúng';setTimeout(()=>{if(hp===0){round++;hp=100;state.zone=(round-1)%3;$('message').textContent='Đã giải cứu một người bạn! Cùng khám phá vùng tiếp theo.';$('round').textContent='Chuyến khám phá '+round;$('hp').value=hp;}phase='ready';lock(false);$('attack').focus();},correct?950:300);}
dialog.addEventListener('cancel',e=>e.preventDefault());$('attack').onclick=ask;$('subject').onchange=()=>{deck=[];};$('hero').onchange=()=>{state.cls=Number($('hero').value);state.element=[1,4,2][state.cls];state.pet=state.element;};
let lastFrame=0;function frame(t){if(!document.hidden&&t-lastFrame>32){drawWorld($('world'),state,{boss:true},event,t);lastFrame=t;}requestAnimationFrame(frame);}requestAnimationFrame(frame);loadAllArt().then(r=>{if(r.some(x=>!x.ok))$('message').textContent='Một số ảnh chưa tải được. Em có thể tải lại trang để thử lại.';});
